import React,{useState}from 'react';
import {NavLink} from "react-router-dom";
import "./Header.css";
import hamburger from "../assets/hamburger.png"
import App from './spline.jsx';
function Header(){
    const[clicked,setclicked]=useState("");
    const[activate,setActivate]=useState(false);
    function Activation(){
      activate ? setActivate(false):setActivate(true);
    }

   
return(
   <header id='Headrer'>
    <div className='Nav_bar'>
        <div className='container'>
          <nav>
            <div>
              <a href='#Headrer'><h2 className='heading' onClick={()=>setclicked("")}>Portfolio.</h2>              </a>
            </div>
            <div className='Lists'>

            <ul className={activate?"list_items":"new_class"}>
                <li onClick={()=>setclicked("About") } className="link_lists"><a href ='#About'  className={clicked==="About"?"active":"a"}>About</a></li>
                <li onClick={()=>setclicked("Skills")} className="link_lists"><a href ='#Skills' className={clicked==="Skills"?"active":"a"}>Skills</a></li>
                <li onClick={()=>setclicked("Projects")} className="link_lists"><a href ='#Projects' className={clicked==="Projects"?"active":"a"}>Projects</a></li>
                 <a href='#Contacts'><button className='btn_contact'>Contact Us</button></a>
            </ul>
            
             <img src={hamburger} className='nav_icon' onClick={Activation}></img>
            </div>
            
          </nav>
        </div>
    </div>
    <div className='intro'>
      <div className='Image_box'>
         
         <App/>
      </div>
      <div className="Text_box">
        <p className='info'>
            Hello Everyone ! <span>Welcome to my portfolio website.</span>
        </p>
        <p className='description'>
           This website is a window into my professional world, showcasing my educational background, diverse skill set, and innovative projects.        </p>
         <a href='#Contacts'><button className='Btn'>Contact Us</button></a> 

      </div>
      
    </div>
   </header>
);


}
export default Header;